if ($PSVersionTable.PSVersion -lt "6.0" -or $IsWindows) {
  # Fix case when both the Windows and Linux builds of Node
  # are installed in the same directory
  $exe=".exe"
  $pathsep=";"
} else {
  $new_node_path="/mnt/c/Users/aleja/Documents/Alejo/SENA/5.TRIMESTRE/02. MARTES/bc-David-express/bootcamp-express/week-2/starter/node_modules/.pnpm/esbuild@0.25.12/node_modules/esbuild/node_modules:/mnt/c/Users/aleja/Documents/Alejo/SENA/5.TRIMESTRE/02. MARTES/bc-David-express/bootcamp-express/week-2/starter/node_modules/.pnpm/esbuild@0.25.12/node_modules:/mnt/c/Users/aleja/Documents/Alejo/SENA/5.TRIMESTRE/02. MARTES/bc-David-express/bootcamp-express/week-2/starter/node_modules/.pnpm/node_modules"
}
if ([string]::IsNullOrEmpty($env_node_path)) {
  $env:NODE_PATH=$new_node_path
} else {
  $env:NODE_PATH="$new_node_path$pathsep$env_node_path"
}

$ret=0
if (Test-Path "$basedir/node$exe") {
  # Support pipeline input
  if ($MyInvocation.ExpectingInput) {
    $input | & "$basedir/node$exe"  "$basedir/../esbuild/bin/esbuild" $args
  } else {
    & "$basedir/node$exe"  "$basedir/../esbuild/bin/esbuild" $args
  }
  $ret=$LASTEXITCODE
} else {
  # Support pipeline input
  if ($MyInvocation.ExpectingInput) {
    $input | & "node$exe"  "$basedir/../esbuild/bin/esbuild" $args
  } else {
    & "node$exe"  "$basedir/../esbuild/bin/esbuild" $args
  }
  $ret=$LASTEXITCODE
}
$env:NODE_PATH=$env_node_path
exit $ret
